import{_ as t,o,c as r,a3 as n}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"Inventory — User Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Inventory — User Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/inventory"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Inventory — User Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/inventory"}]]},"headers":[],"relativePath":"user-guide/inventory.md","filePath":"user-guide/inventory.md","lastUpdated":1787339821000}'),a={name:"user-guide/inventory.md"};function s(i,e,c,d,l,u){return o(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="inventory-—-user-guide" tabindex="-1">Inventory — User Guide <a class="header-anchor" href="#inventory-—-user-guide" aria-label="Permalink to &quot;Inventory — User Guide&quot;">​</a></h1><h2 id="who-can-use-inventory" tabindex="-1">Who can use Inventory <a class="header-anchor" href="#who-can-use-inventory" aria-label="Permalink to &quot;Who can use Inventory&quot;">​</a></h2><p>Install <strong>Products</strong> and then the free <strong>Inventory</strong> module. Your role needs <code>inventory.view</code> to inspect stock, <code>inventory.adjust</code> for changes, and <code>inventory.transfer</code> for transfers.</p><h2 id="stock-levels-and-movements" tabindex="-1">Stock levels and movements <a class="header-anchor" href="#stock-levels-and-movements" aria-label="Permalink to &quot;Stock levels and movements&quot;">​</a></h2><p>Open <strong>Inventory</strong> from the sidebar. Filter stock by product or warehouse, search SKU/name, and use <strong>Low stock</strong> to find stock-tracked products at or below their reorder level. Open a product&#39;s movement history to see the quantity, resulting balance, warehouse, source, note, and actor.</p><h2 id="adjust-stock" tabindex="-1">Adjust stock <a class="header-anchor" href="#adjust-stock" aria-label="Permalink to &quot;Adjust stock&quot;">​</a></h2><p>Select <strong>Adjust stock</strong>, choose a stock-tracked product, optionally choose a warehouse, then select:</p><ul><li><strong>In</strong> — add the entered quantity</li><li><strong>Out</strong> — remove the entered quantity</li><li><strong>Adjust</strong> — set on-hand quantity to the entered value</li></ul><p>Add a note when context is needed. Stock cannot go below zero. If no warehouse is selected, the default <code>MAIN</code> warehouse is used.</p><h2 id="transfers" tabindex="-1">Transfers <a class="header-anchor" href="#transfers" aria-label="Permalink to &quot;Transfers&quot;">​</a></h2><ol><li>Create a transfer with different source and destination warehouses.</li><li>Add each stock-tracked product and quantity.</li><li>Edit or delete it while it is <strong>Draft</strong>.</li><li><strong>Dispatch</strong> it to move it to <strong>In transit</strong>.</li><li><strong>Complete</strong> it to post transfer-out at the source and transfer-in at the destination.</li></ol><p>You can cancel Draft or In-transit transfers. Completed and cancelled transfers are terminal; cancellation does not post stock.</p><h2 id="purchase-order-receipts" tabindex="-1">Purchase order receipts <a class="header-anchor" href="#purchase-order-receipts" aria-label="Permalink to &quot;Purchase order receipts&quot;">​</a></h2><p>Marking a Purchase Order as <strong>Received</strong> posts stock-in once for each line that has a <code>product_id</code> and whose product tracks stock, provided both Products and Inventory are installed. You may choose a warehouse when receiving; otherwise the default warehouse is used. <strong>Partially received</strong> remains acknowledgement-only and posts no stock.</p>',14)])])}const p=t(a,[["render",s]]);export{m as __pageData,p as default};
